// Some portions generated by Codex. Independent Cartesian-product expected tuples, never server output.
const ns='urn:overlay-optional:', xsd='http://www.w3.org/2001/XMLSchema#string';
const result={};
for(const [shape,g,width] of [['small6',10,6],['reference6',100,6],['wide30',100,30],['large6',250,6]]){
 let sum=0n,sum2=0n;
 for(let group=0;group<g;group++)for(let m0=0;m0<10;m0++)for(let m1=0;m1<10;m1++)for(let m2=0;m2<10;m2++){
  const row=[[0,ns+'group/'+group],[2,'Group label '+group,xsd],[2,'Seed '+group,xsd]],members=[m0,m1,m2];
  for(let a=0;a<3;a++){const m=members[a];row.push([0,ns+`node/${group}/${a}/${m}`]);if(width===30)for(let c=0;c<8;c++)row.push(c>=4&&m%7===0?null:[2,`Shared lexical prefix é 漢字 ${group}/${a}/${m}/${c}`,null,'nb']);}
  let h=1n;for(const t of row)h=BigInt.asIntN(64,31n*h+termHash(t));sum=BigInt.asIntN(64,sum+h);const x=BigInt.asUintN(64,h*0x9e3779b97f4a7c15n),mixed=BigInt.asUintN(64,(x<<23n)|(x>>41n))^(BigInt.asUintN(64,h)>>17n);sum2=BigInt.asIntN(64,sum2+mixed);
 }
 result[shape]={rows:g*1000,width,checksum:sum.toString(),checksum2:sum2.toString()};
}
console.log(JSON.stringify(result,null,2));
function javaHash(s){let h=0;for(let i=0;i<s.length;i++)h=(Math.imul(h,31)+s.charCodeAt(i))|0;return BigInt(h);}
function termHash(t){if(t===null)return 0n;let h=31n*javaHash(t[1])+(t[0]===0?1n:t[0]===1?2n:3n);if(t[0]===2){h=31n*h+javaHash(t[2]||(t[3]?'http://www.w3.org/1999/02/22-rdf-syntax-ns#langString':'http://www.w3.org/2001/XMLSchema#string'));h=31n*h+javaHash(t[3]||'');}return BigInt.asIntN(64,h);}
